window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[280]={"id":"280","numero":280,"titre":"Ascite","objectifs":[{"id":"280-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’ascite","contenu":"<p>L'<span class=\"kw-def\">ascite</span> se définit comme un <span class=\"kw-def\">épanchement liquidien péritonéal non sanglant</span>. L'<span class=\"kw-alerte\">hémopéritoine est exclu de cette définition</span>.</p>\n\n      <h5>Rappel physiologique</h5>\n      <p>Un liquide péritonéal est <strong>toujours présent chez le sujet sain</strong>, mais en très petite quantité :</p>\n      <ul>\n        <li><strong>Origine</strong> : <span class=\"kw-def\">liquide interstitiel hépatique</span>, qui passe à travers la capsule du foie par <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">capillaires sinusoïdes</span>.</li>\n        <li><strong>Composition</strong> : liquide <span class=\"kw-bio\">riche en protéines</span> — le liquide interstitiel hépatique est de la lymphe, et <span class=\"kw-clinique\">les</span> capillaires sinusoïdes fenestrés laissent passer les protéines.</li>\n        <li><strong><span class=\"kw-ttt\">Drainage</span></strong> : assuré par <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">lymphatiques sous-péritonéaux</span>.</li>\n      </ul>\n\n      <h5>Présentation clinique</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Prise de poids récente inexpliquée</span>.</li>\n        <li><span class=\"kw-clinique\">Augmentation du volume de l'abdomen</span>.</li>\n        <li>À la percussion, patient en décubitus dorsal : <span class=\"kw-imagerie\">matité mobile et déclive des flancs</span> + <span class=\"kw-imagerie\">tympanisme péri-ombilical</span> — Se/Sp <span class=\"kw-chiffre\">~70 %</span>, dont la présence témoigne d'une <span class=\"kw-clinique\">ascite</span> <span class=\"kw-chiffre\">≥ 1,5 L</span>.</li>\n        <li><span class=\"kw-imagerie\">Signe du flot</span> en appuyant de part et d'autre de l'abdomen.</li>\n        <li><span class=\"kw-clinique\">Diastasis des muscles grands droits</span>, <span class=\"kw-clinique\">déplissement de l'ombilic</span>.</li>\n        <li><span class=\"kw-clinique\">OMI</span> souvent associés (= <span class=\"kw-def\">décompensation œdémato-ascitique</span>).</li>\n      </ul>\n\n      <h5>Diagnostics différentiels</h5>\n      <ul>\n        <li><span class=\"kw-clinique\">Météorisme</span> : accompagne souvent l'<span class=\"kw-clinique\">ascite</span> et peut gêner la reconnaissance d'une ascite peu abondante.</li>\n        <li>Autres causes de <span class=\"kw-imagerie\">matité déclive</span> : globe vésical, volumineux kyste (ovarien, rénal ou hépatique), accumulation stercorale colique — ici la <span class=\"kw-imagerie\">matité n'est pas mobilisable</span> et sa limite supérieure ne dessine pas de courbe concave en haut.</li>\n        <li><span class=\"kw-clinique\">Liquide de ponction sanglant</span> : soit traversée accidentelle d'un vaisseau pariétal (une <span class=\"kw-ttt\">ponction</span> ultérieure ramène un liquide clair), soit <span class=\"kw-alerte\">hémopéritoine</span> — écarté par un <span class=\"kw-bio\">hématocrite du liquide &lt; 1 %</span>, confirmé par une imagerie montrant des caillots dans le péritoine.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 <span class=\"kw-clinique\">Les</span> <strong>complications spécifiques</strong> de l'<span class=\"kw-clinique\">ascite</span> (<span class=\"kw-alerte\">infection spontanée du liquide d'ascite / PBS</span>, <span class=\"kw-alerte\">ascite réfractaire</span>) ne surviennent <strong>quasi-exclusivement</strong> sur ascite de <span class=\"kw-etio\">cirrhose</span>. Détails : voir item 279.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":1},{"id":"280-2","rang":"A","rubrique":"Étiologie","titre":"Connaître les deux causes les plus fréquentes en France","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>deux causes les plus fréquentes d'<span class=\"kw-clinique\">ascite</span> en France</strong> sont la <span class=\"kw-etio\">cirrhose</span> (mécanisme = <strong>excès de production</strong>) et la <span class=\"kw-etio\">carcinose péritonéale</span> (mécanisme = <strong>gêne à la réabsorption</strong>).</p>\n\n      <h5><span class=\"kw-clinique\">Les</span> trois grands mécanismes de constitution d'une <span class=\"kw-clinique\">ascite</span></h5>\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Excès de production</strong></td>\n            <td>\n              <span class=\"kw-etio\">Cirrhose</span> ;<br>\n              <span class=\"kw-etio\">Insuffisance cardiaque</span> (droite ou globale avancée) ;<br>\n              <span class=\"kw-etio\">Syndrome de Budd-Chiari</span> ;<br>\n              <span class=\"kw-etio\">Syndrome néphrotique</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Gêne à la réabsorption</strong></td>\n            <td>\n              <span class=\"kw-etio\">Carcinose péritonéale</span> ;<br>\n              <span class=\"kw-etio\">Tuberculose péritonéale</span> ;<br>\n              <span class=\"kw-etio\">Mésothéliome péritonéal</span> ;<br>\n              <span class=\"kw-etio\">Lymphome péritonéal</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Rupture</span> intra-péritonéale d'un conduit</strong></td>\n            <td>\n              <span class=\"kw-etio\">Canal lymphatique mésentérique</span> (<span class=\"kw-clinique\">ascite</span> <span class=\"kw-bio\">chyleuse</span>) ;<br>\n              <span class=\"kw-etio\">Canal lymphatique hépatique</span> ;<br>\n              <span class=\"kw-etio\">Canal excréteur du pancréas</span> ;<br>\n              <span class=\"kw-etio\">Uretère</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ Chez une <span class=\"kw-clinique\">femme ménopausée</span>, une <span class=\"kw-clinique\">ascite</span> est une <strong><span class=\"kw-etio\">carcinose d'origine ovarienne</span> jusqu'à preuve du contraire</strong>. <span class=\"kw-clinique\">Les</span> 3 régions péritonéales les plus touchées par la carcinose sont le <span class=\"kw-imagerie\">grand épiploon</span>, la <span class=\"kw-imagerie\">coupole diaphragmatique droite</span> et le <span class=\"kw-imagerie\">cul-de-sac de Douglas</span>.</div>\n\n      <h5>Origines de la carcinose péritonéale</h5>\n      <p>Tout cancer peut évoluer sous forme de carcinose. La carcinose représente le <strong>3ᵉ mode de dissémination</strong> des cancers (après <span class=\"kw-clinique\">les</span> voies lymphatique et hématogène).</p>\n      <table >\n        <thead>\n          <tr><th>Origine</th><th>Tumeurs primitives</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Digestive</strong> 🔴</td>\n            <td><span class=\"kw-etio\">Colon-rectum</span>, <span class=\"kw-etio\">estomac</span>, <span class=\"kw-etio\">pancréas</span>, <span class=\"kw-etio\">cholangiocarcinome</span> — <span class=\"kw-ci\">pas le CHC</span> ❌.</td>\n          </tr>\n          <tr>\n            <td><strong>Ovarienne</strong> 🔴</td>\n            <td><span class=\"kw-etio\">Cancer de l'ovaire</span> — « <span class=\"kw-clinique\">ascite</span> chez une femme ménopausée = carcinose ovarienne jusqu'à preuve du contraire ».</td>\n          </tr>\n          <tr>\n            <td><strong>Pseudomyxome péritonéal</strong></td>\n            <td>Maladie gélatineuse du péritoine — origine <span class=\"kw-etio\">appendiculaire</span> ou <span class=\"kw-etio\">ovarienne</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Formes primitives</strong> (rares)</td>\n            <td><span class=\"kw-etio\">Mésothéliome péritonéal</span>, <span class=\"kw-clinique\">carcinome</span> séreux primitif, tumeur desmoplastique à petites cellules, psammocarcinome.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span> · 301 — Tumeur colon - rectum · 304 — Tumeur du foie</em></p>","frequence":1},{"id":"280-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les caractéristiques de liquide d’ascite","contenu":"<p>Toute suspicion d'<span class=\"kw-clinique\">ascite</span> doit bénéficier d'une <span class=\"kw-imagerie\">paracentèse</span> (<span class=\"kw-ttt\">ponction</span> du liquide d'ascite), <strong>urgente</strong> en cas de <span class=\"kw-etio\">cirrhose</span> ou de suspicion d'<span class=\"kw-alerte\">infection du liquide d'ascite</span>.</p>\n\n      <h5>Repère de <span class=\"kw-ttt\">ponction</span></h5>\n      <p><span class=\"kw-ttt\">Ponction</span> sur la ligne joignant l'<span class=\"kw-imagerie\">EIAS gauche</span> et l'<span class=\"kw-imagerie\">ombilic</span>, à la jonction <span class=\"kw-imagerie\">1/3 moyen – 1/3 externe</span>, en pleine matité. Repérage échographique si l'<span class=\"kw-clinique\">ascite</span> n'est pas détectable cliniquement.</p>\n\n      <h5>Aspect macroscopique</h5>\n      <p>L'aspect macroscopique est <strong>très peu spécifique</strong> et ne se substitue jamais aux analyses :</p>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Citrin</span></strong> : le plus souvent.</li>\n        <li><strong><span class=\"kw-imagerie\">Chyleux / lactescent</span></strong> : évoque une compression ou la <span class=\"kw-alerte\">rupture</span> d'un canal lymphatique mésentérique (liquide riche en <span class=\"kw-bio\">triglycérides</span>).</li>\n        <li><strong><span class=\"kw-imagerie\">Hémorragique</span></strong> : évoque une <span class=\"kw-etio\">ascite néoplasique</span>.</li>\n      </ul>\n\n      <h5>Analyses du liquide d'<span class=\"kw-clinique\">ascite</span> (3 tubes)</h5>\n      <table >\n        <thead>\n          <tr><th>Tube</th><th>Analyses et interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Biochimie</strong> (1 tube)</td>\n            <td>\n              <strong>Dosages :</strong> <span class=\"kw-bio\">lipase</span> et <span class=\"kw-bio\">triglycérides</span>, comparés à leur concentration plasmatique ;<br>\n              <strong>Transsudat :</strong> protides <span class=\"kw-chiffre\">&lt; 25 g/L</span> — <span class=\"kw-etio\">syndrome néphrotique</span>, <span class=\"kw-etio\">cirrhose</span> ;<br>\n              <strong>Exsudat :</strong> protides <span class=\"kw-chiffre\">&gt; 25 g/L</span> — <span class=\"kw-etio\">carcinose</span>, <span class=\"kw-etio\">Budd-Chiari</span>, <span class=\"kw-etio\">IC droite</span> ou <span class=\"kw-etio\">péricardite constrictive</span>, <span class=\"kw-etio\">tuberculose</span> ;<br>\n              <strong>GASA</strong> (<span class=\"kw-bio\">albuminémie</span> − protides de l'<span class=\"kw-clinique\">ascite</span>) : <span class=\"kw-chiffre\">≥ 11 g/L</span> très spécifique d'<span class=\"kw-clinique\">HTP</span> (<span class=\"kw-etio\">cirrhose</span>, Budd-Chiari, IC droite ou péricardite) ; <span class=\"kw-chiffre\">&lt; 11 g/L</span> oriente vers carcinose, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">syndrome néphrotique</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Comptage des cellules / anapath</strong> (1 tube)</td>\n            <td>\n              <strong>Infection spontanée :</strong> <span class=\"kw-alerte\">PNN &gt; 250/mm³</span> en l'absence d'infection abdominale contiguë — seule l'<span class=\"kw-clinique\">ascite</span> de la <span class=\"kw-etio\">cirrhose</span> se surinfecte spontanément ;<br>\n              <strong><span class=\"kw-bio\">Hématocrite</span></strong> si liquide <span class=\"kw-etio\">hémorragique</span> : <span class=\"kw-bio\">&lt; 1 %</span> écarte un hémopéritoine ;<br>\n              <strong>PNN très élevés</strong> (&gt; plusieurs milliers/mm³) : font rechercher une <span class=\"kw-alerte\">perforation d'organe creux</span> ;<br>\n              <strong>Ascite tuberculeuse :</strong> <span class=\"kw-bio\">liquide lymphocytaire, leucocytes &gt; 1000/mm³</span> à prédominance lymphocytaire — dosage de l'<span class=\"kw-bio\">ADA (adénosine-désaminase)</span> utile.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bactériologie</strong> (1 tube)</td>\n            <td>Ensemencement, au lit du patient, de <span class=\"kw-chiffre\">≥ 10 mL</span> de liquide dans des flacons d'<span class=\"kw-bio\">hémoculture</span> aérobie et <span class=\"kw-etio\">anaérobie</span>. Le germe est identifié dans environ <span class=\"kw-chiffre\">40 %</span> des cas.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <strong>Mésothéliome péritonéal</strong> (cause rare à connaître) : liquide d'<span class=\"kw-clinique\">ascite</span> très proche de celui de la carcinose — <span class=\"kw-bio\">protides &gt; 25 g/L</span> + <span class=\"kw-bio\">leucocytes pouvant être &gt; 250/mm³</span> ; cytologie inconstamment positive. Principal FR : exposition aux <span class=\"kw-etio\">fibres d'amiante</span>. Imagerie : <span class=\"kw-radio\">épaississement péritonéal</span> localisé ou étendu. Diagnostic histologique.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/peritoneum","label":"Radiopaedia : Peritoneum"},{"href":"https://radiopaedia.org/articles/ascites","label":"Radiopaedia : Ascites"},{"href":"https://radiopaedia.org/articles/peritoneal-metastases","label":"Radiopaedia : Peritoneal metastases"}]},{"id":"280-4","rang":"B","rubrique":"Étiologie","titre":"Connaître les étapes de la démarche diagnostique clinique et para-clinique","contenu":"<div class=\"callout callout-warn\">⚠️ <strong>Objectif tombé en annale</strong> — l'analyse du liquide d'<span class=\"kw-clinique\">ascite</span> est l'étape essentielle de la démarche. Bien maîtriser l'algorithme protides / GASA.</div>\n\n      <h5>Étape 1 — Évaluation clinique initiale</h5>\n      <p><strong>Interrogatoire</strong> — rechercher des antécédents :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Hépatopathie chronique</span> : <span class=\"kw-etio\">cirrhose</span>, <span class=\"kw-etio\">hépatite</span> <span class=\"kw-etio\">virale</span>, <span class=\"kw-etio\">consommation d'<span class=\"kw-etio\">alcool</span></span>.</li>\n        <li><span class=\"kw-clinique\">Cancer primitif</span> : néoplasie digestive, ovarienne ou pancréatique.</li>\n        <li><span class=\"kw-clinique\">Cardiopathie</span> : <span class=\"kw-etio\">insuffisance cardiaque</span> droite, péricardite.</li>\n      </ul>\n      <p><strong>Examen clinique</strong> — rechercher des signes associés :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Cirrhose</span></strong> : signes d'<span class=\"kw-clinique\">HTP</span>, signes d'<span class=\"kw-clinique\">IHC</span>, complications de <span class=\"kw-etio\">cirrhose</span>.</li>\n        <li><strong>IC droite</strong> : <span class=\"kw-clinique\">OMI</span>, <span class=\"kw-clinique\">turgescence jugulaire</span>, <span class=\"kw-clinique\">reflux hépato-jugulaire</span>.</li>\n        <li><strong>Carcinose péritonéale</strong> : <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">ascite</span> exsudative.</li>\n      </ul>\n\n      <h5>Étape 2 — <span class=\"kw-ttt\">Ponction</span> d'<span class=\"kw-clinique\">ascite</span> (analyse du liquide)</h5>\n      <ul>\n        <li><strong>Cytologie</strong> : recherche de <span class=\"kw-bio\">cellules tumorales</span>.</li>\n        <li><strong>Bactériologie</strong> : recherche d'une infection (ex. <span class=\"kw-clinique\">péritonite</span> <span class=\"kw-etio\">bactérienne</span> spontanée).</li>\n        <li><strong>Biochimie</strong> : dosage des protéines et du <span class=\"kw-bio\">gradient d'albumine sang-ascite (GASA)</span>.</li>\n      </ul>\n\n      <h5>Étape 3 — Bilan <span class=\"kw-ttt\">biologique</span> sanguin et urinaire orienté</h5>\n      <table >\n        <thead>\n          <tr><th>Cible diagnostique</th><th>Examens biologiques orientés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Cirrhose</span></strong></td>\n            <td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">TP / facteur V</span>, <span class=\"kw-bio\">albuminémie</span>, <span class=\"kw-bio\">bilirubine</span>, <span class=\"kw-bio\">EPP</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Syndrome néphrotique</span></strong></td>\n            <td><span class=\"kw-bio\">Protéinurie des 24 h</span>, <span class=\"kw-bio\">EPP</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Insuffisance cardiaque</span></strong></td>\n            <td><span class=\"kw-bio\">BNP / NT-proBNP</span> (si clinique et <span class=\"kw-imagerie\">ETT</span> en faveur)</td>\n          </tr>\n          <tr>\n            <td><strong>Fonction rénale</strong></td>\n            <td><span class=\"kw-bio\">Ionogramme</span> sanguin et urinaire, <span class=\"kw-bio\">créatinine</span> — souvent perturbée quelle que soit la cause</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Étape 4 — Interprétation : algorithme étiologique</h5>\n      <table >\n        <thead>\n          <tr><th>Protides</th><th>GASA</th><th>Diagnostic(s)</th><th>Explorations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"2\"><strong>Transsudat</strong><br><span class=\"kw-chiffre\">&lt; 25 g/L</span></td>\n            <td><span class=\"kw-chiffre\">≥ 11 g/L</span></td>\n            <td><strong><span class=\"kw-etio\">Cirrhose</span></strong></td>\n            <td><span class=\"kw-imagerie\">Écho-<span class=\"kw-imagerie\">Doppler</span></span> abdominal</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\">&lt; 11 g/L</span></td>\n            <td><strong><span class=\"kw-etio\">Syndrome néphrotique</span></strong></td>\n            <td><span class=\"kw-bio\">Bandelette urinaire</span>, <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">EPP</span></td>\n          </tr>\n          <tr>\n            <td rowspan=\"2\"><strong>Exsudat</strong><br><span class=\"kw-chiffre\">&gt; 25 g/L</span></td>\n            <td><span class=\"kw-chiffre\">≥ 11 g/L</span></td>\n            <td><strong><span class=\"kw-etio\">Budd-Chiari</span>, <span class=\"kw-etio\">IC droite</span>, <span class=\"kw-etio\">péricardite constrictive</span></strong></td>\n            <td><span class=\"kw-imagerie\">Écho-<span class=\"kw-imagerie\">Doppler</span></span>, <span class=\"kw-imagerie\">TDM</span> abdominale, <span class=\"kw-imagerie\">ETT</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\">&lt; 11 g/L</span></td>\n            <td><strong><span class=\"kw-etio\">Carcinose péritonéale</span>, <span class=\"kw-etio\">tuberculose péritonéale</span></strong></td>\n            <td>Anapath du liquide, <span class=\"kw-imagerie\">TDM</span> abdominale, <span class=\"kw-bio\">PCR</span> BK</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <strong>Causes rares à reconnaître par profil biochimique particulier</strong> (hors algorithme protides/GASA) :<br>\n        — <strong><span class=\"kw-etio\">Ascite chyleuse</span></strong> : aspect <span class=\"kw-imagerie\">lactescent</span>, <span class=\"kw-bio\">triglycérides ascite &gt; plasma</span>, riche en chylomicrons → <span class=\"kw-alerte\">rupture</span> / compression du <span class=\"kw-imagerie\">canal lymphatique mésentérique</span> ;<br>\n        — <strong><span class=\"kw-etio\">Ascite pancréatique</span></strong> : <span class=\"kw-bio\">lipase / amylase</span> élevées dans l'<span class=\"kw-clinique\">ascite</span> + protides élevés → suite de <span class=\"kw-clinique\">pancréatite aiguë nécrosante</span> ou <span class=\"kw-clinique\">pancréatite chronique</span> ; bilan par <span class=\"kw-imagerie\">TDM / IRM</span>.</div>\n\n      <h5>Étape 5 — Examens de 2ᵉ ligne (si doute diagnostique persistant)</h5>\n      <div class=\"callout callout-info\">📌 L'<span class=\"kw-clinique\">ascite</span> cirrhotique typique se diagnostique <strong>sans examen invasif</strong> : la <span class=\"kw-bio\">biopsie</span> hépatique et l'étude hémodynamique sont réservées aux cas douteux.</div>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Étude hémodynamique</span></strong> (cathétérisme de la veine jugulaire interne) — quand la clinique, le liquide et l'<span class=\"kw-imagerie\">échographie</span> ne tranchent pas entre atteinte cardiaque et <span class=\"kw-etio\">cirrhose</span> : gradient de pression veineuse hépatique <span class=\"kw-chiffre\">&gt; 10 mmHg</span> = <span class=\"kw-etio\">cirrhose</span> ; pression de l'oreillette droite <span class=\"kw-chiffre\">&gt; 12 mmHg</span> = IC droite ou péricardite <span class=\"kw-clinique\">constrictive</span>. Permet aussi une <span class=\"kw-imagerie\">biopsie hépatique transveineuse</span> dans le même temps.</li>\n        <li><strong><span class=\"kw-imagerie\">Cœlioscopie avec biopsies péritonéales</span></strong> — si la cytologie du liquide n'est pas concluante et <span class=\"kw-clinique\">les</span> causes communes exclues : prélèvements sur une zone anormale <strong>ET</strong> sur une zone d'aspect normal. Excellent rendement pour <span class=\"kw-etio\">carcinose péritonéale</span>, <span class=\"kw-clinique\">mésothéliome</span> et <span class=\"kw-etio\">tuberculose péritonéale</span>. <span class=\"kw-ci\">CI : état précaire, laparotomie antérieure, troubles de l'hémostase non corrigés.</span></li>\n        <li><strong><span class=\"kw-imagerie\">Endoscopie digestive haute</span></strong> (place limitée) — recherche d'une <span class=\"kw-clinique\">tumeur digestive</span> en cas de suspicion de <span class=\"kw-etio\">carcinose péritonéale</span> ; recherche de <span class=\"kw-clinique\">varices œsophagiennes</span> / signes d'<span class=\"kw-clinique\">HTP</span> en cas de <span class=\"kw-etio\">cirrhose</span>.</li>\n      </ul>\n\n      <h5>Mesures associées</h5>\n      <div class=\"callout callout-info\">📌 <strong>Indications à la perfusion d'<span class=\"kw-bio\">albumine</span> :</strong> <span class=\"kw-ttt\">ponction</span> évacuatrice <span class=\"kw-chiffre\">&gt; 5 L</span> ; <span class=\"kw-alerte\">infection du liquide d'<span class=\"kw-clinique\">ascite</span></span> (<span class=\"kw-chiffre\">J1</span>–J3) ; <span class=\"kw-alerte\">syndrome hépato-rénal</span>. Posologie : <span class=\"kw-ttt\">1 flacon d'albumine 20 % pour 2 L ponctionnés</span>.</div>\n      <div class=\"callout callout-info\">📌 <strong>Indications à l'<span class=\"kw-ttt\">antibioprophylaxie</span> de l'<span class=\"kw-alerte\">infection du liquide d'<span class=\"kw-clinique\">ascite</span></span> :</strong><br>\n        — ascite avec protides <span class=\"kw-chiffre\">&lt; 10 g/L</span> → <span class=\"kw-ttt\">norfloxacine</span> ;<br>\n        — hémorragie digestive → <span class=\"kw-ttt\">norfloxacine ou C3G</span> pendant <span class=\"kw-chiffre\">7 jours</span> ;<br>\n        — ATCD d'infection du liquide d'ascite, en <span class=\"kw-def\">prévention secondaire</span> → <span class=\"kw-ttt\">norfloxacine</span>.</div>\n      <div class=\"callout callout-warn\">⚠️ <span class=\"kw-ci\">Évacuation contre-indiquée en cas d'hypovolémie ou d'état de choc</span> : seule la <span class=\"kw-ttt\">ponction</span> exploratrice est alors possible. Évacuation limitée à <span class=\"kw-chiffre\">≤ 6–8 L par ponction</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span> · 234 — <span class=\"kw-etio\">Insuffisance cardiaque</span> · 259 — <span class=\"kw-bio\">Protéinurie</span> - <span class=\"kw-etio\">syndrome néphrotique</span> · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":6},{"id":"280-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens d’imagerie de première intention devant une ascite","contenu":"<h5><span class=\"kw-imagerie\">Échographie</span>-<span class=\"kw-imagerie\">Doppler</span> abdominale — examen de 1ʳᵉ intention</h5>\n      <p>L'<span class=\"kw-imagerie\">échographie-Doppler abdominale</span> est l'<strong>examen d'imagerie de <span class=\"kw-chiffre\">première intention</span></strong> devant une <span class=\"kw-clinique\">ascite</span> (tombé en annale). Très performante, elle :</p>\n      <ul>\n        <li>confirme l'<span class=\"kw-clinique\">ascite</span> et détecte <span class=\"kw-clinique\">les</span> épanchements peu abondants, cloisonnés ou infracliniques, limités aux poches et récessus péritonéaux (<span class=\"kw-imagerie\">cul-de-sac de Douglas</span>, espace inter-hépatorénal) ;</li>\n        <li>guide la <span class=\"kw-ttt\">ponction</span> ;</li>\n        <li>oriente le <span class=\"kw-def\">diagnostic étiologique</span>.</li>\n      </ul>\n\n      <h5>Orientations étiologiques échographiques</h5>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Signes échographiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Cirrhose</span></td>\n            <td><span class=\"kw-radio\">Contours hépatiques irréguliers</span> (bosselés), dysmorphie avec atrophie du lobe droit et hypertrophie du lobe gauche</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Cirrhose décompensée</span></td>\n            <td><span class=\"kw-imagerie\">Ascite</span> + <span class=\"kw-radio\">splénomégalie</span> + <span class=\"kw-radio\">voies de dérivation</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">HTP sévère</span></td>\n            <td><span class=\"kw-radio\">Flux porte inversé</span> au <span class=\"kw-imagerie\">Doppler</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Dépistage</span> du <span class=\"kw-alerte\">carcinome hépatocellulaire</span></td>\n            <td><span class=\"kw-radio\">Nodules hétérogènes</span> (plages hyper et hypoéchogènes)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">IC droite</span> ou <span class=\"kw-etio\">péricardite constrictive</span></td>\n            <td><span class=\"kw-radio\">Dilatation des veines hépatiques</span> ou de la VCI</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Carcinose</span> ou <span class=\"kw-etio\">mésothéliome péritonéal</span></td>\n            <td><span class=\"kw-radio\">Épaississement pariétal</span> du péritoine</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Tumeur ovarienne ou digestive</span></td>\n            <td><span class=\"kw-imagerie\">Masse</span> de l'ovaire ou de l'appareil digestif</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Syndrome de Budd-Chiari</span></td>\n            <td><span class=\"kw-radio\">Obstruction des veines hépatiques</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Autres imageries</h5>\n      <ul>\n        <li><span class=\"kw-imagerie\">TDM / IRM</span> : <strong>pas en 1ʳᵉ intention</strong> — intérêt seulement si l'<span class=\"kw-imagerie\">échographie</span> est peu contributive (tumeurs de l'appareil digestif, de l'ovaire, du péritoine ; affections pancréatiques).</li>\n        <li>Si <span class=\"kw-clinique\">cardiopathie</span> suspectée → <span class=\"kw-imagerie\">ETT</span> : <span class=\"kw-clinique\">les</span> veines hépatiques sont toujours dilatées lorsque l'<span class=\"kw-clinique\">ascite</span> est d'origine cardiaque.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ La <span class=\"kw-imagerie\">TDM</span> et l'<span class=\"kw-imagerie\">IRM</span> ne sont <strong>pas</strong> des examens de <span class=\"kw-chiffre\">première intention</span> devant une <span class=\"kw-clinique\">ascite</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-ttt\">Paracentèse</span> (<span class=\"kw-ttt\">ponction</span> d'<span class=\"kw-clinique\">ascite</span>) <span class=\"q\">— geste de 1ʳᵉ intention</span></strong></p><p>prélèvement pour <span class=\"kw-bio\">analyse</span> (cytologie · bactériologie · biochimie)</p><ul><li><span class=\"kw-ttt\">Ponction d'ascite</span> systématique devant toute suspicion d'<span class=\"kw-clinique\">ascite</span></li><li><span class=\"kw-alerte\">Urgente</span> si <span class=\"kw-etio\">cirrhose</span> ou suspicion d'<span class=\"kw-etio\">infection du liquide d'ascite</span></li><li><span class=\"kw-imagerie\">Repérage échographique</span> si <span class=\"kw-clinique\">ascite</span> indétectable cliniquement</li></ul><p><strong>Évacuation de grande abondance</strong></p><p><span class=\"kw-ci\">évacuation contre-indiquée si hypovolémie ou état de choc</span> → seule la <span class=\"kw-ttt\">ponction</span> exploratrice est possible</p><ul><li>Maximum <span class=\"kw-chiffre\">≤ 6-8 L</span> par <span class=\"kw-ttt\">ponction</span></li><li><span class=\"kw-ttt\">Perfusion d'albumine</span> si <span class=\"kw-etio\">cirrhotique</span> ou <span class=\"kw-ttt\">ponction</span> <span class=\"kw-chiffre\">&gt; 5 L</span> : <span class=\"kw-chiffre\">1 flacon d'albumine 20 % pour 2 L</span> ponctionnés</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">PNN &gt; 250/mm³</span> dans le liquide → <span class=\"kw-etio\">infection spontanée du liquide d'ascite (PBS)</span>, quasi exclusivement sur <span class=\"kw-clinique\">ascite</span> de <span class=\"kw-etio\">cirrhose</span></li><li><span class=\"kw-alerte\">PNN &gt; plusieurs milliers/mm³</span> → rechercher une <span class=\"kw-alerte\">perforation d'organe creux</span></li><li><span class=\"kw-alerte\">Ascite chez une femme ménopausée</span> = <span class=\"kw-etio\">carcinose d'origine ovarienne</span> jusqu'à preuve du contraire</li><li><span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">syndrome occlusif</span>, <span class=\"kw-clinique\">nodule ombilical</span> ou induration des cicatrices → <span class=\"kw-etio\">carcinose péritonéale</span></li><li><span class=\"kw-alerte\">Liquide de ponction hémorragique</span> : doser l'<span class=\"kw-bio\">hématocrite</span> — <span class=\"kw-alerte\">hémopéritoine</span> si <span class=\"kw-chiffre\">≥ 1 %</span></li><li><span class=\"kw-alerte\">Hypovolémie / état de choc</span> → <span class=\"kw-ci\">contre-indication à l'évacuation</span> de l'<span class=\"kw-clinique\">ascite</span></li></ul>","principes":"<p><strong>Règle d'or :</strong> toute <span class=\"kw-clinique\">ascite</span> impose une <span class=\"kw-ttt\">paracentèse exploratrice</span> avec <span class=\"kw-bio\">analyse du liquide</span> ; la prise en charge est avant tout <span class=\"kw-def\">étiologique</span>.</p><p><strong>Perfusion d'<span class=\"kw-bio\">albumine</span> <span class=\"q\">— indications</span></strong></p><p>posologie : <span class=\"kw-chiffre\">1 flacon d'albumine 20 % pour 2 L</span> ponctionnés</p><ul><li><span class=\"kw-ttt\">Ponction</span> évacuatrice <span class=\"kw-chiffre\">&gt; 5 L</span></li><li><span class=\"kw-etio\">Infection du liquide d'ascite</span> (<span class=\"kw-chiffre\">J1-J3</span>)</li><li><span class=\"kw-etio\">Syndrome hépato-rénal</span></li></ul><p><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> de l'<span class=\"kw-alerte\">infection du liquide d'<span class=\"kw-clinique\">ascite</span></span></strong></p><ul><li><span class=\"kw-clinique\">Ascite</span> avec <span class=\"kw-bio\">protides &lt; 10 g/L</span> → <span class=\"kw-ttt\">norfloxacine</span></li><li><span class=\"kw-etio\">Hémorragie digestive</span> → <span class=\"kw-ttt\">norfloxacine</span> ou <span class=\"kw-ttt\">C3G</span> pendant <span class=\"kw-chiffre\">7 jours</span></li><li>ATCD d'<span class=\"kw-alerte\">infection du liquide d'<span class=\"kw-clinique\">ascite</span></span> (prévention 2ᵃⁱʳᵉ) → <span class=\"kw-ttt\">norfloxacine</span></li></ul><p><strong>Occlusion sur carcinose péritonéale <span class=\"q\">— traitement symptomatique</span></strong></p><p><span class=\"kw-ci\">métoclopramide contre-indiqué en cas d'occlusion</span> (action pro-kinétique → risque d'inhalation)</p><ul><li>Patient à jeun + <span class=\"kw-ttt\">réhydratation IV/SC</span> ; <span class=\"kw-ttt\">SNG</span> si <span class=\"kw-clinique\">vomissements</span> francs ou distension gastrique</li><li><span class=\"kw-ttt\">Antalgique</span> + <span class=\"kw-ttt\">antiémétique (neuroleptique injectable)</span> + <span class=\"kw-ttt\">IPP</span> + <span class=\"kw-ttt\">anticholinergique</span> + <span class=\"kw-ttt\">corticothérapie courte</span> (<span class=\"kw-ttt\">méthylprednisolone</span> / <span class=\"kw-ttt\">dexaméthasone</span>)</li><li>± <span class=\"kw-ttt\">analogue de la somatostatine</span> si pas de levée à <span class=\"kw-chiffre\">J4</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/peritoneum","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ascites","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/peritoneal-metastases","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Analyse du liquide d'ascite — Paracentèse : protides, GASA, cytologie, bactériologie, lipase/TG","detail":"<h4>Démarche diagnostique étiologique d'une <span class=\"kw-clinique\">ascite</span> — Analyse du liquide d'ascite (<span class=\"kw-ttt\">paracentèse</span>) : protides + GASA</h4>","branches":[{"to":"t-chyleuse","label":"Aspect chyleux / lactescent (TG ascite > plasma)","color":"blue"},{"to":"t-pancreatique","label":"Lipase / amylase élevées (contexte de pancréatite)","color":"blue"},{"to":"q-gasa-bas","label":"Protides < 25 g/L (transsudat)","color":"amber"},{"to":"q-gasa-haut","label":"Protides > 25 g/L (exsudat)","color":"amber"}]},{"id":"t-chyleuse","kind":"terminal","label":"Ascite chyleuse","color":"blue","detail":"<h4>Liquide</h4><ul><li>Aspect <span class=\"kw-imagerie\">lactescent</span></li><li><span class=\"kw-bio\">Triglycérides</span> plus élevés que dans le plasma, riche en <span class=\"kw-bio\">chylomicrons</span></li></ul><h4>Mécanisme</h4><ul><li><span class=\"kw-alerte\">Rupture</span> ou hyperpression d'un <span class=\"kw-etio\">canal lymphatique mésentérique</span></li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Traumatisme chirurgical</span></li><li><span class=\"kw-etio\">Hyperpression lymphatique</span> (lymphome, métastases ganglionnaires, <span class=\"kw-ttt\">radiothérapie</span>)</li><li><span class=\"kw-etio\">Maladie de Waldenström</span></li><li><span class=\"kw-etio\">Cirrhose</span>, <span class=\"kw-etio\">insuffisance cardiaque droite</span></li></ul>"},{"id":"t-pancreatique","kind":"terminal","label":"Ascite pancréatique","color":"blue","detail":"<h4>Liquide</h4><ul><li>Riche en enzymes (<span class=\"kw-bio\">lipase</span>, <span class=\"kw-bio\">amylase</span>) et en <span class=\"kw-bio\">protides</span></li></ul><h4>Mécanisme</h4><ul><li>Atteinte du <span class=\"kw-etio\">canal excréteur du pancréas</span></li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Pancréatite aiguë nécrosante</span> (<span class=\"kw-clinique\">nécrose</span>)</li><li><span class=\"kw-etio\">Pancréatite chronique</span> (hyperpression canalaire)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">TDM</span> / <span class=\"kw-imagerie\">IRM</span> abdominale</li></ul>"},{"id":"q-gasa-bas","kind":"decision","label":"Gradient albumine sang-ascite (GASA) ? — GASA = albuminémie − protides de l'ascite","branches":[{"to":"t-cirrhose","label":"GASA ≥ 11 g/L","color":"blue"},{"to":"t-nephrotique","label":"GASA < 11 g/L","color":"amber"}]},{"id":"t-cirrhose","kind":"terminal","label":"Cirrhose","color":"blue","detail":"<h4>Liquide</h4><ul><li><span class=\"kw-bio\">Protides &lt; 25 g/L</span>, <span class=\"kw-bio\">GASA ≥ 11 g/L</span> (très spécifique d'<span class=\"kw-def\">hypertension portale</span>)</li><li><span class=\"kw-bio\">Pauvre en leucocytes</span> (PNN &lt; 250/mm³), pas de cellule anormale</li></ul><h4>Mécanisme</h4><ul><li><span class=\"kw-imagerie\">Capillaires sinusoïdes</span> fibrosés → perte de fenestration → liquide pauvre en protéines</li></ul><h4>Exploration</h4><ul><li><span class=\"kw-imagerie\">Écho-doppler abdominal</span> : contours bosselés, dysmorphie, <span class=\"kw-clinique\">splénomégalie</span>, circulation collatérale, inversion du flux porte</li></ul><h4>Renvoi</h4><ul><li>Item 279 — <span class=\"kw-etio\">Cirrhose</span></li></ul>"},{"id":"t-nephrotique","kind":"terminal","label":"Syndrome néphrotique","color":"amber","detail":"<h4>Liquide</h4><ul><li><span class=\"kw-bio\">Protides &lt; 25 g/L</span>, <span class=\"kw-bio\">GASA &lt; 11 g/L</span>, pauvre en <span class=\"kw-bio\">leucocytes</span></li></ul><h4>Mécanisme</h4><ul><li><span class=\"kw-etio\">Hypoalbuminémie</span> et fuite protéique rénale</li></ul><h4>Exploration</h4><ul><li><span class=\"kw-bio\">Bandelette urinaire</span>, <span class=\"kw-bio\">protéinurie des 24 h</span> (&gt;<span class=\"kw-chiffre\"> 3 g</span>/<span class=\"kw-chiffre\">24 h</span>)</li><li><span class=\"kw-bio\">EPP</span>, <span class=\"kw-bio\">albuminémie</span></li></ul>"},{"id":"q-gasa-haut","kind":"decision","label":"Gradient albumine sang-ascite (GASA) ? — GASA = albuminémie − protides de l'ascite","branches":[{"to":"t-htp-exsudat","label":"GASA ≥ 11 g/L","color":"amber"},{"to":"t-carcinose-tuberculose","label":"GASA < 11 g/L","color":"red"}]},{"id":"t-htp-exsudat","kind":"terminal","label":"Budd-Chiari · IC droite · péricardite constrictive","color":"amber","detail":"<h4>Liquide</h4><ul><li><span class=\"kw-bio\">Protides &gt; 25 g/L</span>, <span class=\"kw-bio\">GASA ≥ 11 g/L</span>, <span class=\"kw-bio\">pauvre en leucocytes</span></li></ul><h4>Mécanisme</h4><ul><li><span class=\"kw-imagerie\">Capillaires sinusoïdes</span> dilatés mais à fenestration préservée → perméables aux protéines</li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Syndrome de Budd-Chiari</span> (thrombose des veines sus-hépatiques)</li><li><span class=\"kw-etio\">Insuffisance cardiaque droite / globale</span></li><li><span class=\"kw-etio\">Péricardite constrictive</span></li></ul><h4>Exploration</h4><ul><li><span class=\"kw-imagerie\">Écho-doppler abdominal</span> (dilatation des veines hépatiques / VCI), <span class=\"kw-imagerie\">ETT</span></li></ul>"},{"id":"t-carcinose-tuberculose","kind":"terminal","label":"Carcinose · tuberculose péritonéale","color":"red","detail":"<h4>Liquide</h4><ul><li><span class=\"kw-bio\">Protides &gt; 25 g/L</span>, <span class=\"kw-bio\">GASA &lt; 11 g/L</span>, riche en cellules</li></ul><h4>Carcinose péritonéale</h4><ul><li><span class=\"kw-bio\">Cellules tumorales</span> possibles</li><li><span class=\"kw-imagerie\">TDM TAP injectée</span> : nodules péritonéaux (grand épiploon)</li><li><span class=\"kw-ttt\">Cœlioscopie exploratrice</span> + biopsies histologiques</li><li><span class=\"kw-alerte\">Femme ménopausée</span> = origine <span class=\"kw-etio\">ovarienne</span> jusqu'à preuve du contraire</li></ul><h4><span class=\"kw-etio\">Tuberculose</span> péritonéale</h4><ul><li><span class=\"kw-bio\">Leucocytes &gt; 1000/mm³</span> à prédominance lymphocytaire</li><li><span class=\"kw-bio\">Adénosine-désaminase (ADA)</span></li><li><span class=\"kw-ttt\">Cœlioscopie</span> + <span class=\"kw-ttt\">biopsie</span> péritonéale (granulomes), <span class=\"kw-bio\">PCR BK</span></li></ul>"}]},"cards":[{"i":"101a58dae3c3","n":280,"o":"280-2","u":"Étiologie","t":"Connaître les deux causes les plus fréquentes en France","q":"Quel est le mécanisme principal de l'ascite liée à la carcinose péritonéale ?","a":"<p>Le mécanisme principal de l'ascite liée à la carcinose péritonéale est une <strong>gêne à la réabsorption</strong> du liquide ascitique par le péritoine.</p>"},{"i":"962222194e9b","n":280,"o":"280-2","u":"Étiologie","t":"Connaître les deux causes les plus fréquentes en France","q":"Comment doit-on interpréter une ascite chez une femme ménopausée ?","a":"<p>Chez une femme ménopausée, une ascite doit être considérée comme une <strong>carcinose d'origine ovarienne</strong> jusqu'à preuve du contraire.</p>"},{"i":"c519d060340f","n":280,"o":"280-2","u":"Étiologie","t":"Connaître les deux causes les plus fréquentes en France","q":"Quelles sont les deux causes d'ascite les plus fréquentes en France ?","a":"<p>Les deux causes d'ascite les plus fréquentes en France sont :</p><ul><li>La <strong>cirrhose</strong>.</li><li>La <strong>carcinose péritonéale</strong>.</li></ul>"},{"i":"eca6147a4e50","n":280,"o":"280-2","u":"Étiologie","t":"Connaître les deux causes les plus fréquentes en France","q":"Quel est le mécanisme principal de l'ascite liée à la cirrhose ?","a":"<p>Le mécanisme principal de l'ascite liée à la cirrhose est un <strong>excès de production</strong> de liquide ascitique.</p>"},{"i":"0af98d49aa8f","n":280,"o":"280-5","u":"Examens complémentaires","t":"Connaître les examens d’imagerie de première intention devant une ascite","q":"Face à une ascite, quels sont les signes échographiques pouvant orienter vers une cirrhose ?","a":"<p>Devant une ascite, les signes échographiques orientant vers une cirrhose sont des <strong>contours hépatiques irréguliers (bosselés)</strong> et une <strong>dysmorphie hépatique</strong> avec atrophie du lobe droit et hypertrophie du lobe gauche.</p>"},{"i":"3ff6206ef541","n":280,"o":"280-5","u":"Examens complémentaires","t":"Connaître les examens d’imagerie de première intention devant une ascite","q":"Quand envisager la réalisation d'un scanner (TDM) ou d'une IRM devant une ascite ?","a":"<p>Le scanner (TDM) ou l'IRM ne sont <strong>pas des examens de première intention</strong> devant une ascite. Ils sont envisagés seulement si l'échographie est peu contributive, notamment pour explorer des tumeurs de l'appareil digestif, de l'ovaire, du péritoine ou des affections pancréatiques.</p>"},{"i":"91258c6121ff","n":280,"o":"280-5","u":"Examens complémentaires","t":"Connaître les examens d’imagerie de première intention devant une ascite","q":"Quels signes échographiques de cirrhose décompensée on peut retrouver face à une ascite ?","a":"<p>Face à une ascite, une cirrhose décompensée est évoquée par l'association d'une ascite, d'une <strong>splénomégalie</strong> et de <strong>voies de dérivation</strong>.</p>"},{"i":"99deda47f3b7","n":280,"o":"280-5","u":"Examens complémentaires","t":"Connaître les examens d’imagerie de première intention devant une ascite","q":"Quel est l'examen d'imagerie de première intention à réaliser devant une ascite ?","a":"<p>L'examen d'imagerie de première intention devant une ascite est l'<strong>échographie-Doppler abdominale</strong>.</p>"},{"i":"9e08e9d5e88f","n":280,"o":"280-5","u":"Examens complémentaires","t":"Connaître les examens d’imagerie de première intention devant une ascite","q":"Quels sont les signes échographiques pouvant évoquer un syndrome de Budd-Chiari en présence d'une ascite ?","a":"<p>En présence d'une ascite, les signes échographiques évoquant un syndrome de Budd-Chiari sont l'<strong>obstruction des veines hépatiques</strong>.</p>"},{"i":"c8690779a385","n":280,"o":"280-5","u":"Examens complémentaires","t":"Connaître les examens d’imagerie de première intention devant une ascite","q":"Quels sont les rôles de l'échographie-Doppler abdominale dans la prise en charge d'une ascite ?","a":"<ul><li>Elle <strong>confirme l'ascite</strong> et détecte même les épanchements peu abondants, cloisonnés ou infracliniques.</li><li>Elle sert de <strong>guide pour la ponction</strong> d'ascite.</li><li>Elle <strong>oriente le diagnostic étiologique</strong> de l'ascite.</li></ul>"}]};